using System;using System.Text;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckMusicalParking {
public enum ParkingPhase {Countdown,Music,Scramble,RoundResult,Complete}
public sealed class ParkingMatch:SportsEventSession {
 public SportsEventTruck[] trucks;public ParkingBay[] bays;public SportsEventCamera arenaCamera;public SportsCameraFit framing;public AudioSource music;public TextMesh[] identities;public bool[] active=new bool[8];public int[] secured=new int[8];public float[] capture=new float[8],routeProgress=new float[8],debt=new float[8];public ParkingPhase Phase{get;private set;}public int Round{get;private set;}public int Remaining{get;private set;}public int Winner{get;private set;}=-1;public int Eliminated{get;private set;}=-1;public int TotalCaptures{get;private set;}public int EliminatedMask{get;private set;}public bool ReplayRound{get;private set;}public readonly float[] penalty=new float[8];public readonly bool[] returned=new bool[8];public float Age{get;private set;}public int Seed{get;private set;}
 float musicDuration,clock;readonly float[] offenseAge=new float[8],collisionGrace=new float[8],stationary=new float[8];readonly int[] offenses=new int[8],ownerSnapshot=new int[8];readonly bool[] offenseLatched=new bool[8];readonly float[] angles=new float[8],lastLegal=new float[8],reaction=new float[8],claimStart=new float[8],distances=new float[8];readonly int[] selected=new int[8];readonly bool[] inside=new bool[8];readonly Vector3[] executionOffset=new Vector3[8];System.Random random;readonly StringBuilder text=new StringBuilder(1200);
 public override string Title=>"TRUCK MUSICAL PARKING";public override int MinimumPlayers=>8;public override int MaximumPlayers=>8;public override bool UsesAction=>false;public override int OptionCount=>1;public override string OptionLabel=>"EIGHT TRUCKS · CLAIM A SPACE TO SURVIVE";
 public override string Help=>"CIRCLE WHILE THE MUSIC PLAYS\nEight trucks; up to four humans with independent sources, AI fills. Stay between the two yellow loop boundaries. Red bays are CLOSED; the public horn and green signs start the scramble even with music muted. AI hears the same horn.\n\nPARK THE WHOLE TRUCK\nThe physical chassis footprint must be fully inside the painted bay, upright, supported and below0.9m/s for one continuous second. Cosmetic labels do not count. The strip fills only while eligible. Rivals may push before capture. Once secured, each truck owns exactly one bay and becomes a protected obstacle. Simultaneous claims use rotating seeded priority.\n\nRED LOCK: PARKING PENALTY\nCutting inside, entering a closed bay or camping during music earns a3s capture lockout; repeated offenses increase it to6s. Small boundary tolerance and brief actual impact recovery are allowed. Return to the yellow band first, then the countdown runs only DURING PARKING. It cannot be served during music. AI follows the same rule.\n\nSECURE A BAY TO ADVANCE\nAfter28s EVERY truck without its own secured space is out. Partial capture does not count. The next round has survivors minus one bays. One survivor wins. If no one captures, the same roster replays: no arbitrary elimination. Eliminated trucks do not force the camera wider. Rematch retains names, colors, sources and difficulty. Pause/disconnect preserves motion, clocks and ownership. Offline only.";
 public override string Header=>Title+" | ROUND "+Round+" | "+Remaining+" TRUCKS · "+Mathf.Max(0,Remaining-1)+" SPACES";
 public override string Status=>Phase==ParkingPhase.Countdown?"READY · "+Mathf.CeilToInt(3-Age):Phase==ParkingPhase.Music?"MUSIC PLAYING · STAY IN THE YELLOW BAND":Phase==ParkingPhase.Scramble?(Age<1?"HORN!  PARK NOW":"PARK NOW · "+Mathf.Max(0,28-Age).ToString("F0")+"s LEFT"):ReplayRound?"NO BAYS CLAIMED · SAME CONTENDERS REPLAY":"ROUND LOCKED · "+ParkingRules.Count(EliminatedMask)+" ELIMINATED";
 public override string Standings{get{text.Clear();for(int i=0;i<8;i++){text.Append("<color=#").Append(ColorUtility.ToHtmlStringRGB(setup.players[i].color)).Append('>').Append(setup.players[i].name).Append("</color>  ").Append(Eligibility(i)).Append(i==7?"":"\n");}return text.ToString();}}
 public override string Results=>(Winner<0?"NO WINNER":setup.players[Winner].name+" WINS THE LAST SPACE")+"\n\n"+Round+" rounds · "+TotalCaptures+" physical captures\n\n"+Standings;
 public override float ParticipantProgress(int slot)=>capture[slot];public override bool ParticipantLocked(int slot)=>penalty[slot]>0;
 public string Eligibility(int i){if(!active[i])return "OUT";if(secured[i]>=0)return "SECURED";if(penalty[i]>0)return "PARKING PENALTY "+Mathf.CeilToInt(penalty[i])+"s"+(returned[i]?"":" · RETURN TO BAND");if(Phase==ParkingPhase.Music)return "CIRCLE THE YELLOW BAND";if(capture[i]>0)return "CAPTURE "+Mathf.RoundToInt(capture[i]*100)+"%";int b=Nearest(i);if(b>=0&&bays[b].Owner>=0)return "BAY ALREADY SECURED";if(trucks[i].body.linearVelocity.magnitude>=.9f)return "SLOW DOWN";return "MOVE FULLY INSIDE";}
 int Nearest(int i){int best=-1;float d=float.PositiveInfinity;for(int b=0;b<8;b++)if(bays[b].gameObject.activeSelf){float value=(trucks[i].body.position-bays[b].transform.position).sqrMagnitude;if(value<d){d=value;best=b;}}return best;}
 public override bool ValidateSources(out string reason){if(!base.ValidateSources(out reason))return false;int humans=0;for(int i=0;i<8;i++)if(setup.players[i].source!=BowlingSource.AI)humans++;if(humans>4){reason="At most four human sources; AI fills eight competitors.";return false;}return true;}
 protected override void BeginGame(){Seed=UnityEngine.Random.Range(1,100000);random=new System.Random(Seed);Round=0;clock=0;Remaining=8;Winner=Eliminated=-1;TotalCaptures=0;for(int i=0;i<8;i++){active[i]=true;offenses[i]=0;}BeginRound();}
 void BeginRound(){if(!ReplayRound)Round++;ReplayRound=false;EliminatedMask=0;Age=0;Phase=ParkingPhase.Countdown;music.Stop();musicDuration=5+(float)random.NextDouble()*7;int place=0;for(int i=0;i<8;i++){secured[i]=selected[i]=-1;capture[i]=routeProgress[i]=debt[i]=0;lastLegal[i]=-10;penalty[i]=offenseAge[i]=stationary[i]=0;returned[i]=offenseLatched[i]=false;collisionGrace[i]=clock+1.25f;claimStart[i]=float.PositiveInfinity;float angle=place*360f/Remaining;var p=new Vector3(Mathf.Sin(angle*Mathf.Deg2Rad)*30,.55f,Mathf.Cos(angle*Mathf.Deg2Rad)*23);var tangent=new Vector3(Mathf.Cos(angle*Mathf.Deg2Rad)*30,0,-Mathf.Sin(angle*Mathf.Deg2Rad)*23);if(active[i]){trucks[i].visuals.gameObject.SetActive(true);trucks[i].Prepare(p,Quaternion.LookRotation(tangent));trucks[i].Power(false);trucks[i].body.isKinematic=true;place++;}else trucks[i].Park(new Vector3(-46+i*4,.5f,-36));angles[i]=Angle(p);float error=Mathf.Lerp(.6f,.08f,(int)setup.players[i].difficulty*.5f);executionOffset[i]=new Vector3(((float)random.NextDouble()*2-1)*error,0,((float)random.NextDouble()*2-1)*error);reaction[i]=Mathf.Lerp(.75f,.16f,(int)setup.players[i].difficulty*.5f)+(float)random.NextDouble()*.13f;}for(int b=0;b<8;b++){int index=(b+Round-1)%8;float x=(index%4-1.5f)*11,z=index<4?-7:7;bays[b].transform.SetPositionAndRotation(new Vector3(x,.035f,z),Quaternion.Euler(0,index<4?0:180,0));bays[b].ResetBay(b<Remaining-1,false);bays[b].caption.transform.rotation=Quaternion.Euler(90,0,0);}Gate();}
 static float Angle(Vector3 p)=>Mathf.Atan2(p.x/30,p.z/23)*Mathf.Rad2Deg;
 float LoopStep(int i,float dt){var p=trucks[i].body.position;float radius=new Vector2(p.x/30,p.z/23).magnitude;float angle=Angle(p);float delta=Mathf.DeltaAngle(angles[i],angle);angles[i]=angle;float advance=radius>.76f&&radius<1.22f&&delta>0&&delta<30?delta*Mathf.Deg2Rad*26:0;if(advance>.005f){lastLegal[i]=Age;routeProgress[i]+=advance;}return advance;}
 public void Horn(){if(Phase!=ParkingPhase.Music)return;for(int i=0;i<8;i++)if(active[i]){if((InAnyBay(i)||stationary[i]>1.8f||ParkingRules.Radius(trucks[i].body.position)<ParkingRules.InnerBand-.045f)&&clock>=collisionGrace[i]&&!offenseLatched[i])Penalize(i);selected[i]=-1;debt[i]=0;}Phase=ParkingPhase.Scramble;Age=0;music.Stop();foreach(var bay in bays)if(bay.gameObject.activeSelf)bay.SetOpen(true);feedback.Play(2,0,true);}
 bool InAnyBay(int i){foreach(var bay in bays)if(bay.gameObject.activeSelf&&ParkingRules.Contains(trucks[i].shape,trucks[i].body,bay.transform.position,bay.transform.rotation,bay.size))return true;return false;}
 public void CollisionRecovery(int i,float incomingNormalSpeed){if(i>=0&&i<8&&incomingNormalSpeed>1)collisionGrace[i]=clock+.9f;}
 void Penalize(int i){offenses[i]++;penalty[i]=offenses[i]==1?3:6;returned[i]=false;offenseLatched[i]=true;offenseAge[i]=0;capture[i]=0;claimStart[i]=float.PositiveInfinity;}
 void Penalties(int i,float dt){var t=trucks[i];bool band=ParkingRules.InBand(t.body.position);if(band){returned[i]=true;if(t.body.linearVelocity.magnitude>.55f){offenseAge[i]=0;offenseLatched[i]=false;}}if(Phase==ParkingPhase.Scramble){if(returned[i])penalty[i]=Mathf.Max(0,penalty[i]-dt);return;}stationary[i]=t.body.linearVelocity.magnitude<.55f?stationary[i]+dt:0;bool violation=ParkingRules.Radius(t.body.position)<ParkingRules.InnerBand-.045f||InAnyBay(i)||stationary[i]>1.8f;if(!violation){offenseAge[i]=0;return;}if(clock<collisionGrace[i]){offenseAge[i]=0;return;}offenseAge[i]+=dt;if(offenseAge[i]>.65f&&!offenseLatched[i])Penalize(i);}
 Vector2 CircleAI(int i){var t=trucks[i];float theta=Angle(t.body.position)*Mathf.Deg2Rad+.38f;return DriveTo(i,new Vector3(Mathf.Sin(theta)*30,0,Mathf.Cos(theta)*23),10,false);}
 Vector2 DriveTo(int i,Vector3 target,float desired,bool parking){var t=trucks[i];var delta=Vector3.ProjectOnPlane(target-t.body.position,Vector3.up);float angle=Vector3.SignedAngle(Vector3.ProjectOnPlane(t.transform.forward,Vector3.up),delta,Vector3.up);bool reverse=parking&&Mathf.Abs(angle)>112;float along=Vector3.Dot(t.body.linearVelocity,t.transform.forward);float steer=Mathf.Clamp((reverse?Mathf.DeltaAngle(angle,180):angle)/28,-1,1)*(reverse?-1:1);if(Mathf.Abs(angle)>45&&!reverse)desired*=.45f;float throttle=Mathf.Clamp(((reverse?-desired:desired)-along)*.65f,-1,1);return new Vector2(steer,throttle);}
 bool WholeInside(int i,int b)=>b>=0&&bays[b].gameObject.activeSelf&&bays[b].Owner<0&&ParkingRules.Contains(trucks[i].shape,trucks[i].body,bays[b].transform.position,bays[b].transform.rotation,bays[b].size);
 Vector2 ParkAI(int i){if(Age<reaction[i]||penalty[i]>0)return CircleAI(i);var t=trucks[i];int bay=selected[i];if(bay<0||!bays[bay].gameObject.activeSelf||bays[bay].Owner>=0){float best=float.PositiveInfinity;bay=-1;for(int j=0;j<8;j++)if(bays[j].gameObject.activeSelf&&bays[j].Owner<0){float score=Vector3.Distance(t.body.position,bays[j].transform.position)+(i*7+j*11+Seed)%9;for(int k=0;k<8;k++)if(k!=i&&active[k]&&Vector3.Distance(trucks[k].body.position,bays[j].transform.position)<3)score+=9;if(score<best){best=score;bay=j;}}selected[i]=bay;capture[i]=0;claimStart[i]=float.PositiveInfinity;}if(bay<0)return Vector2.zero;if(WholeInside(i,bay))return Vector2.zero;var target=bays[bay].transform.position+executionOffset[i];float distance=Vector3.ProjectOnPlane(target-t.body.position,Vector3.up).magnitude;
 // A captured chassis is a real protected obstacle. Route locally around it, never keep pushing its old bay.
 for(int k=0;k<8;k++)if(k!=i&&active[k]&&secured[k]>=0){var a=Vector3.ProjectOnPlane(target-t.body.position,Vector3.up);float length=a.magnitude;if(length<.1f)break;var direction=a/length;var rel=Vector3.ProjectOnPlane(trucks[k].body.position-t.body.position,Vector3.up);float along=Vector3.Dot(rel,direction);if(along>0&&along<Mathf.Min(length,8)&&Vector3.Cross(direction,rel).magnitude<3.1f){var side=Vector3.Cross(Vector3.up,direction);float sign=Vector3.Dot(rel,side)>0?-1:1;target=trucks[k].body.position+side*sign*4-direction*1.8f;break;}}
 return DriveTo(i,target,Mathf.Clamp(distance*1.5f,.4f,11),true);}
 void Brake(int i){trucks[i].command=Vector2.zero;foreach(var w in trucks[i].wheels){w.MotorTorque=0;w.BrakeTorque=trucks[i].brakeTorque;w.SteerAngle=0;}}
 protected override void Simulate(float dt){Age+=dt;clock+=dt;if(Phase==ParkingPhase.Countdown){if(Age>=3){Age=0;Phase=ParkingPhase.Music;for(int i=0;i<8;i++)if(active[i]){trucks[i].body.isKinematic=false;trucks[i].Power(true);}music.Play();}return;}if(Phase==ParkingPhase.RoundResult){if(Age>=2.5f){if(Remaining==1){Phase=ParkingPhase.Complete;for(int i=0;i<8;i++)if(active[i])Winner=i;EndMatch();}else BeginRound();}return;}if(Phase!=ParkingPhase.Music&&Phase!=ParkingPhase.Scramble)return;
 for(int i=0;i<8;i++)if(active[i]&&secured[i]<0){LoopStep(i,dt);Penalties(i,dt);bool bot=setup.players[i].source==BowlingSource.AI;var drive=bot?(Phase==ParkingPhase.Music?CircleAI(i):ParkAI(i)):commands[i];bool hold=bot&&Phase==ParkingPhase.Scramble&&penalty[i]<=0&&Age>=reaction[i]&&WholeInside(i,selected[i]);if(hold&&trucks[i].body.linearVelocity.magnitude>.12f)Brake(i);else trucks[i].TickDrive(drive);}
 if(Phase==ParkingPhase.Music){if(Age>=musicDuration)Horn();return;}
 for(int i=0;i<8;i++){inside[i]=false;if(!active[i]||secured[i]>=0)continue;int candidate=-1;if(penalty[i]<=0&&Supported(i)&&trucks[i].body.linearVelocity.magnitude<.9f&&Vector3.Dot(trucks[i].transform.up,Vector3.up)>.8f&&trucks[i].body.position.y<2.5f)for(int b=0;b<8;b++)if(bays[b].gameObject.activeSelf&&bays[b].Owner<0&&ParkingRules.Contains(trucks[i].shape,trucks[i].body,bays[b].transform.position,bays[b].transform.rotation,bays[b].size)){candidate=b;break;}if(candidate<0){capture[i]=0;claimStart[i]=float.PositiveInfinity;}else{inside[i]=true;if(float.IsInfinity(claimStart[i]))claimStart[i]=Age;capture[i]=Mathf.Min(1,(Age-claimStart[i])/ParkingRules.CaptureSeconds);selected[i]=candidate;}}
 for(int b=0;b<8;b++)if(bays[b].gameObject.activeSelf&&bays[b].Owner<0){int owner=-1;for(int i=0;i<8;i++)if(active[i]&&secured[i]<0&&inside[i]&&selected[i]==b&&capture[i]>=1&&(owner<0||ParkingRules.BetterClaim(claimStart[i],i,claimStart[owner],owner,(Seed+Round)%8)))owner=i;if(owner>=0)Secure(owner,b);}
 int unparked=0;for(int i=0;i<8;i++)if(active[i]&&secured[i]<0)unparked++;if(unparked==1||Age>=28)Resolve();}
 bool Supported(int i){var t=trucks[i];foreach(var w in t.wheels)if(w.enabled&&w.IsGrounded)return true;var p=t.body.position+Vector3.up*.05f;return Physics.Raycast(p,Vector3.down,.65f,~(1<<2),QueryTriggerInteraction.Ignore);}
 public bool Secure(int slot,int bay){if(slot<0||slot>=8||bay<0||bay>=8||!active[slot]||secured[slot]>=0||!bays[bay].gameObject.activeSelf||!bays[bay].Open||bays[bay].Owner>=0)return false;secured[slot]=bay;capture[slot]=1;bays[bay].Secure(slot,setup.players[slot].color,setup.players[slot].name);trucks[slot].Power(false);if(!trucks[slot].body.isKinematic)trucks[slot].body.linearVelocity=trucks[slot].body.angularVelocity=Vector3.zero;trucks[slot].body.isKinematic=true;for(int i=0;i<8;i++)if(i!=slot&&selected[i]==bay){selected[i]=-1;capture[i]=0;claimStart[i]=float.PositiveInfinity;}TotalCaptures++;feedback.Play(3,0,true);Pulse(slot,.15f,.09f);return true;}
 void Resolve(){if(Phase!=ParkingPhase.Scramble)return;for(int b=0;b<8;b++)ownerSnapshot[b]=bays[b].Owner;var outcome=ParkingRules.Resolve(active,secured,ownerSnapshot);ReplayRound=outcome.Replay;EliminatedMask=outcome.EliminatedMask;Eliminated=ParkingRules.First(EliminatedMask);if(!ReplayRound){for(int i=0;i<8;i++)if((EliminatedMask&(1<<i))!=0)active[i]=false;Remaining=outcome.Remaining;Winner=outcome.Winner;}Phase=ParkingPhase.RoundResult;Age=0;foreach(var t in trucks)t.Power(false);music.Stop();feedback.Play(4,0,true);Gate();Debug.Log("PARKING_ROUND_LOCK round="+Round+" eliminatedMask="+EliminatedMask+" remaining="+Remaining+" replay="+ReplayRound+" captures="+TotalCaptures);}
 void FrameActive(float dt){if(framing==null)return;bool initialized=false;Bounds desired=new Bounds();for(int i=0;i<8;i++)if(active[i]){var bounds=trucks[i].shape.bounds;if(!initialized){desired=bounds;initialized=true;}else desired.Encapsulate(bounds);}foreach(var bay in bays)if(bay.gameObject.activeSelf){var box=new Bounds(bay.transform.position,new Vector3(bay.size.x,2,bay.size.y));if(!initialized){desired=box;initialized=true;}else desired.Encapsulate(box);}if(!initialized)return;desired.Expand(Phase==ParkingPhase.Scramble?4:7);var current=framing.arenaBounds;float blend=1-Mathf.Exp(-Mathf.Max(0,dt)*2.5f);current.center=Vector3.Lerp(current.center,desired.center,blend);var offset=desired.center-current.center;offset=new Vector3(Mathf.Abs(offset.x),Mathf.Abs(offset.y),Mathf.Abs(offset.z));current.extents=Vector3.Max(Vector3.Lerp(current.extents,desired.extents,blend),desired.extents+offset);framing.arenaBounds=current;framing.Apply();}
 protected override void Present(float dt){if(music!=null)music.volume=Live?settings.music*.35f:0;if(trucks==null)return;if(Running&&!Finished)FrameActive(dt);for(int i=0;i<8;i++){identities[i].transform.position=trucks[i].body.position+Vector3.up*2.5f;identities[i].text=setup.players[i].name;identities[i].color=active[i]?setup.players[i].color:Color.gray;}for(int b=0;b<8;b++){float value=0;Color color=Color.white;for(int i=0;i<8;i++)if(active[i]&&selected[i]==b&&capture[i]>value){value=capture[i];color=setup.players[i].color;}bays[b].Progress(value,color);}}
 protected override void StopGame(){if(music!=null)music.Stop();if(trucks!=null)foreach(var t in trucks)t.Park(t.body.position);}protected override void StopSounds(){if(trucks!=null)foreach(var t in trucks)t.StopSound();}protected override void SetPaused(bool pause){if(music==null)return;if(pause)music.Pause();else if(Phase==ParkingPhase.Music)music.UnPause();}
}
